package com.vandorlabs.neoforge.programmer;
import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.programmer.ProgrammerStatus;
import io.netty.buffer.Unpooled;
import java.util.Collections;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerPlayer;
/** Actual vanilla packet codec with an uninstalled client mirror that cannot own items. */
final class ProgrammerPacketChecks {
 private static int checks;
 private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Programmer packet: "+why);}
 private record Encoded(CompoundTag tag,int bytes){}
 private static Encoded packet(NativeProgrammerEntity tile){var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),tile.getLevel().registryAccess());try{var sent=tile.getUpdatePacket();ClientboundBlockEntityDataPacket.STREAM_CODEC.encode(buffer,sent);int bytes=buffer.readableBytes();var received=ClientboundBlockEntityDataPacket.STREAM_CODEC.decode(buffer);need(!buffer.isReadable()&&received.getTag().equals(sent.getTag())&&received.getPos().equals(tile.getBlockPos())&&received.getType()==tile.getType(),"vanilla packet round trip");return new Encoded(received.getTag(),bytes);}finally{buffer.release();}}
 static void run(NativeProgrammerEntity owner,ServerPlayer player){var registries=owner.getLevel().registryAccess();player.setPos(owner.getBlockPos().getX()+.5,owner.getBlockPos().getY(),owner.getBlockPos().getZ()-2);owner.clearContent();owner.tick();owner.setItem(0,NativeCredentialItems.dataChip(4));owner.setItem(1,NativeCredentialItems.dataChip(0));need(owner.configure(player,new NativeProgrammerDraft(false,true,"Bounded network journal",Collections.nCopies(8,"A".repeat(512)))),"maximum journal configured");var baseline=packet(owner);need(!baseline.tag.contains("PhaseOnly")&&baseline.tag.contains("Journal"),"content full projection");var mirror=new NativeProgrammerEntity(owner.getType(),owner.getBlockPos(),owner.getBlockState());mirror.loadWithComponents(baseline.tag,registries);need(!mirror.inert()&&mirror.journalView()!=null&&mirror.getItem(1).isEmpty(),"safe baseline");var layout=mirror.journalView().journal;need(owner.turnJournalPage(player,1),"page turn");var page=packet(owner);need(page.tag.getBoolean("PhaseOnly")&&!page.tag.contains("Journal")&&!page.tag.contains("Draft")&&!page.tag.contains("Items"),"compact no ownership or text");mirror.loadWithComponents(page.tag,registries);mirror.loadWithComponents(baseline.tag,registries);mirror.loadWithComponents(page.tag,registries);need(mirror.journalView().page==1&&mirror.journalView().journal==layout,"page, repeated and old full retain layout");var fresh=new NativeProgrammerEntity(owner.getType(),owner.getBlockPos(),owner.getBlockState());fresh.loadWithComponents(page.tag,registries);need(fresh.journalView()==null&&fresh.visual().sequence()==0,"phase cannot establish baseline");
 need(owner.program(player),"program");var writing=packet(owner);need(!writing.tag.getBoolean("PhaseOnly"),"output and writing full");mirror.loadWithComponents(writing.tag,registries);need(mirror.status()==ProgrammerStatus.WRITING,"writing round trip");layout=mirror.journalView().journal;for(int i=0;i<20;i++)owner.tick();var complete=packet(owner);mirror.loadWithComponents(complete.tag,registries);need(complete.tag.getBoolean("PhaseOnly")&&mirror.status()==ProgrammerStatus.COMPLETE&&mirror.journalView().journal==layout,"complete compact preserves layout");for(int i=0;i<60;i++)owner.tick();var ready=packet(owner);mirror.loadWithComponents(ready.tag,registries);mirror.loadWithComponents(complete.tag,registries);need(ready.tag.getBoolean("PhaseOnly")&&mirror.status()==ProgrammerStatus.READY,"ready and old phase");
 owner.setItem(1,NativeCredentialItems.dataChip(0));need(owner.configure(player,new NativeProgrammerDraft(false,true,"Coalesced",Collections.nCopies(8,"B".repeat(512))))&&owner.turnJournalPage(player,1),"coalesced changes");var coalesced=packet(owner);mirror.loadWithComponents(coalesced.tag,registries);need(!coalesced.tag.getBoolean("PhaseOnly")&&mirror.draft().title().equals("Coalesced")&&mirror.journalView().page==1,"content flag survives later page update");need(page.bytes<baseline.bytes/10&&complete.bytes<writing.bytes/10&&ready.bytes==complete.bytes,"measured reduction");System.out.println("[vandorlabs][programmer-packets] PASS checks="+checks+" fullPage="+baseline.bytes+" compactPage="+page.bytes+" fullWriting="+writing.bytes+" compactComplete="+complete.bytes+" compactReady="+ready.bytes+" messages=5->5");owner.clearContent();
 }
}
